/* Baseline MVP — local-first basketball season tracker. */
const KEY='baseline-basketball-v1';
const cloudConfig=window.RAIDERS_CONFIG||{};
const cloudKey=cloudConfig.publishableKey||cloudConfig.anonKey;
const cloudMode=Boolean(cloudConfig.supabaseUrl&&cloudKey);
const adminEmail=String(cloudConfig.adminEmail||'').trim().toLowerCase();
let supabaseClient=null,adminAllowed=false,cloudSession=null,cloudWriteQueue=Promise.resolve(),cloudRevision=0;
const uid=()=>Math.random().toString(36).slice(2,10);
const initial=()=>({seasons:[{id:'s1',name:'2026/27',active:true}],teams:[{id:'t1',name:'1st Team',shortName:'1ST',active:true},{id:'t2',name:'2nd Team',shortName:'2ND',active:true}],players:[{id:'p1',name:'Ben',active:true},{id:'p2',name:'Dave',active:true},{id:'p3',name:'John',active:true},{id:'p4',name:'Smith',active:true}],contributors:[{id:'c1',name:'Alex',active:true},{id:'c2',name:'Sam',active:true}],statTypes:[{key:'points',name:'Points',active:true},{key:'fouls',name:'Fouls',active:true}],games:[
 {id:'g1',seasonId:'s1',teamId:'t1',date:'2026-10-03',opponentName:'Harrogate Hawks',venueType:'HOME',ourScore:72,opponentScore:68,notes:'Season opener',createdAt:new Date().toISOString(),appearances:[{playerId:'p1',status:'PLAYED',stats:{points:14,fouls:2}},{playerId:'p2',status:'PLAYED',stats:{points:12,fouls:1}},{playerId:'p3',status:'PLAYED',stats:{points:8,fouls:3}},{playerId:'p4',status:'ATTENDED_DID_NOT_PLAY',stats:{points:0,fouls:0}}],tableDuty:['c1']},
 {id:'g2',seasonId:'s1',teamId:'t2',date:'2026-10-10',opponentName:'York Vikings',venueType:'AWAY',ourScore:61,opponentScore:70,notes:'',createdAt:new Date().toISOString(),appearances:[{playerId:'p1',status:'PLAYED',stats:{points:17,fouls:1}},{playerId:'p3',status:'PLAYED',stats:{points:11,fouls:2}},{playerId:'p4',status:'PLAYED',stats:{points:9,fouls:2}}],tableDuty:[]},
 {id:'g3',seasonId:'s1',teamId:'t1',date:'2026-10-17',opponentName:'Leeds Eagles',venueType:'AWAY',ourScore:78,opponentScore:71,notes:'',createdAt:new Date().toISOString(),appearances:[{playerId:'p1',status:'PLAYED',stats:{points:19,fouls:3}},{playerId:'p2',status:'PLAYED',stats:{points:15,fouls:2}},{playerId:'p4',status:'PLAYED',stats:{points:13,fouls:1}}],tableDuty:[]}
]});
let db=load(),view='dashboard',teamFilter='ALL',playerQuery='',selectedPlayer=null,selectedGame=null,gameDraft=null;
function load(){try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&Array.isArray(v.games))return v}catch{}return initial()}
function save(){if(!cloudMode){localStorage.setItem(KEY,JSON.stringify(db));return true}if(!adminAllowed){toast('Sign in as the tracker admin to edit data.');return false}const snapshot=JSON.parse(JSON.stringify(db)),revision=++cloudRevision;cloudWriteQueue=cloudWriteQueue.then(async()=>{const {error}=await supabaseClient.from('tracker_state').upsert({id:'main',data:snapshot,updated_at:new Date().toISOString()});if(error)throw error}).catch(async error=>{console.error('Tracker cloud save failed',error);toast('Could not save to the shared tracker. Check your connection and database setup.');if(revision===cloudRevision){try{const {data}=await supabaseClient.from('tracker_state').select('data').eq('id','main').maybeSingle();if(data?.data&&Array.isArray(data.data.games)){db=data.data;render()}}catch{}}});return true}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currentSeason=()=>db.seasons.find(s=>s.active)||db.seasons[0];
const seasonGames=(seasonId=currentSeason()?.id)=>db.games.filter(g=>g.seasonId===seasonId);
const team=id=>db.teams.find(t=>t.id===id)||{name:'Removed team',shortName:'—'};
const player=id=>db.players.find(p=>p.id===id)||{name:'Unknown player'};
const contributor=id=>db.contributors.find(c=>c.id===id)||{name:'Unknown'};
const result=g=>g.ourScore>g.opponentScore?'WIN':g.ourScore<g.opponentScore?'LOSS':'DRAW';
const fmtDate=(s,opt={day:'numeric',month:'short',year:'numeric'})=>s?new Date(`${s}T12:00:00`).toLocaleDateString('en-GB',opt):'—';
function filteredGames(filter=teamFilter){return seasonGames().filter(g=>filter==='ALL'||g.teamId===filter)}
function teamStats(games){const w=games.filter(g=>result(g)==='WIN').length,l=games.filter(g=>result(g)==='LOSS').length,pf=games.reduce((n,g)=>n+Number(g.ourScore||0),0),pa=games.reduce((n,g)=>n+Number(g.opponentScore||0),0);return{gp:games.length,w,l,pf,pa,wpct:w+l?w/(w+l)*100:0,avgf:games.length?pf/games.length:0,avga:games.length?pa/games.length:0}}
function playerStats(pid,games){const appearances=[];for(const g of games)for(const a of g.appearances||[])if(a.playerId===pid)appearances.push({g,a});const played=appearances.filter(x=>x.a.status==='PLAYED'),attended=appearances.filter(x=>['PLAYED','ATTENDED_DID_NOT_PLAY'].includes(x.a.status)),unavailable=appearances.filter(x=>x.a.status==='UNAVAILABLE');const wins=played.filter(x=>result(x.g)==='WIN').length,losses=played.filter(x=>result(x.g)==='LOSS').length,points=played.reduce((n,x)=>n+Number(x.a.stats?.points||0),0),fouls=played.reduce((n,x)=>n+Number(x.a.stats?.fouls||0),0);return{gp:played.length,points,fouls,ppg:played.length?points/played.length:0,wins,losses,wpct:wins+losses?wins/(wins+losses)*100:0,attended:attended.length,unavailable:unavailable.length,attendanceRate:attended.length+unavailable.length?attended.length/(attended.length+unavailable.length)*100:null,played,attendedRows:attended}}
function tableDutyStats(games){const counts=new Map();for(const g of games)if(g.venueType==='HOME')for(const id of g.tableDuty||[])counts.set(id,(counts.get(id)||0)+1);return counts}
function statsFor(pid,filter){const gs=filter==='ALL'?seasonGames():seasonGames().filter(g=>g.teamId===filter);return playerStats(pid,gs)}
function allStatsRows(filter='ALL'){return db.players.filter(p=>!p.deleted).map(p=>({p,s:statsFor(p.id,filter),all:playerStats(p.id,seasonGames())})).filter(x=>x.s.gp||x.s.attended).sort((a,b)=>b.s.points-a.s.points)}
function playerLink(id,name,className='player-inline-link'){return '<button type="button" class="'+className+'" data-player="'+esc(id)+'">'+esc(name)+'</button>'}
function bindPlayerLinks(root=document){root.querySelectorAll('[data-player]').forEach(el=>{el.onclick=e=>{e.stopPropagation();showPlayer(el.dataset.player)}})}
function avatar(name){const colors=['','orange','blue','pink'];const i=Math.abs([...name].reduce((a,c)=>a+c.charCodeAt(0),0))%colors.length;return `<span class="avatar ${colors[i]}">${esc(name.split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase())}</span>`}
function nav(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view)});const titles={dashboard:'Overview',games:'Games',stats:'Statistics',players:'Players',more:'More'};document.getElementById('top-title').textContent=titles[view]||'Overview'}
function shell(){const sel=document.getElementById('season-select');sel.innerHTML=db.seasons.map(s=>`<option value="${esc(s.id)}" ${s.active?'selected':''}>${esc(s.name)} season</option>`).join('');document.getElementById('season-sidebar-name').textContent=`${currentSeason()?.name||'Season'} Season`;document.getElementById('today-label').textContent=new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});nav()}
function heading(title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(currentSeason()?.name||'SEASON')} SEASON</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function metric(label,value,foot,icon){return `<div class="metric-card"><div class="metric-top">${label}<span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot||'This season'}</div></div>`}
function filterSelect(){return `<select class="select-small" id="team-select"><option value="ALL">All teams</option>${db.teams.map(t=>`<option value="${t.id}" ${teamFilter===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`}
function resultTag(g){return `<span class="result-tag ${result(g).toLowerCase()}">${result(g)}</span>`}
function gameRows(games){if(!games.length)return `<div class="empty-state"><div class="empty-icon">▤</div><strong>No games recorded yet</strong><p>Add your first game to start building the season record.</p><button class="button button-primary" onclick="openGame()">＋ Add game</button></div>`;return `<div class="game-list">${[...games].sort((a,b)=>b.date.localeCompare(a.date)).map(g=>`<div class="game-card" data-game="${g.id}"><div class="game-date"><strong>${fmtDate(g.date,{day:'numeric',month:'short'})}</strong><small>${new Date(`${g.date}T12:00:00`).getFullYear()}</small></div><div class="game-main"><strong>${esc(g.opponentName)}</strong><small>${esc(team(g.teamId).name)} · ${g.venueType} ${g.tableDuty?.length?`· <span class="duty-chip">◷ Table duty</span>`:''}</small></div><div class="game-score">${g.ourScore} – ${g.opponentScore}<small>${resultTag(g)}</small></div></div>`).join('')}</div>`}
function dashboardLeaderboards(games){
  const players=db.players.filter(p=>!p.deleted).map(p=>({p,s:playerStats(p.id,games)}));
  const awayGames=games.filter(g=>g.venueType==='AWAY');
  const awayRows=db.players.filter(p=>!p.deleted).map(p=>({p,n:awayGames.filter(g=>(g.appearances||[]).some(a=>a.playerId===p.id&&['PLAYED','ATTENDED_DID_NOT_PLAY'].includes(a.status))).length}));
  const dutyMap=new Map();
  games.filter(g=>g.venueType==='HOME').forEach(g=>(g.tableDuty||[]).forEach(id=>dutyMap.set(id,(dutyMap.get(id)||0)+1)));
  const dutyRows=db.contributors.map(c=>({c,n:dutyMap.get(c.id)||0}));
  return [
    {key:'points',label:'Top scorer',rows:players,name:r=>r.p.name,score:r=>r.s.gp?r.s.points:null,format:r=>r.s.gp?r.s.points+' points':'—',details:r=>r.s.gp+' GP · '+r.s.wins+'–'+r.s.losses},
    {key:'ppg',label:'Highest PPG',rows:players,name:r=>r.p.name,score:r=>r.s.gp?Number(r.s.ppg.toFixed(1)):null,format:r=>r.s.gp?r.s.ppg.toFixed(1)+' PPG':'—',details:r=>r.s.gp+' GP · '+r.s.points+' points'},
    {key:'games',label:'Most appearances',rows:players,name:r=>r.p.name,score:r=>r.s.gp?r.s.gp:null,format:r=>r.s.gp?r.s.gp+' games':'—',details:r=>r.s.wins+'–'+r.s.losses+' · '+r.s.points+' points'},
    {key:'win-pct',label:'Best player win %',rows:players,name:r=>r.p.name,score:r=>r.s.wins+r.s.losses?Number(r.s.wpct.toFixed(1)):null,summaryEligible:r=>r.s.gp>=2,format:r=>r.s.wins+r.s.losses?r.s.wpct.toFixed(1)+'%':'—',details:r=>r.s.wins+'–'+r.s.losses+' · '+r.s.gp+' GP'},
    {key:'fouls',label:'Most fouls',rows:players,name:r=>r.p.name,score:r=>r.s.gp?r.s.fouls:null,format:r=>r.s.gp?r.s.fouls+' fouls':'—',details:r=>r.s.gp+' GP · '+r.s.points+' points'},
    {key:'away',label:'Most away attendance',rows:awayRows,name:r=>r.p.name,score:r=>awayGames.length&&r.n?r.n:null,format:r=>r.n?r.n+' games':'—',details:r=>r.n+' of '+awayGames.length+' away games'},
    {key:'duty',label:'Most table duty',rows:dutyRows,name:r=>r.c.name,score:r=>r.n?r.n:null,format:r=>r.n?r.n+' games':'—',details:r=>r.n+' home games'}
  ];
}
function sortedLeaderRows(spec){
  return spec.rows.slice().sort((a,b)=>{
    const av=spec.score(a),bv=spec.score(b);
    if(av===null&&bv!==null)return 1;
    if(bv===null&&av!==null)return -1;
    return (bv??0)-(av??0)||spec.name(a).localeCompare(spec.name(b));
  });
}
function highlightCard(spec){
  const rows=sortedLeaderRows(spec).filter(r=>spec.score(r)!==null&&(!spec.summaryEligible||spec.summaryEligible(r)));
  const top=rows.length?spec.score(rows[0]):null;
  const leaders=top===null?[]:rows.filter(r=>spec.score(r)===top);
  const names=leaders.length?leaders.map(spec.name).join(', '):'—';
  const value=leaders.length?spec.format(leaders[0])+(leaders.length>1?' · '+leaders.length+' tied':''):'No results yet';
  const linkedNames=leaders.length&&leaders[0].p?leaders.map(r=>playerLink(r.p.id,spec.name(r),'player-inline-link leader-name-link')).join(', '):esc(names);
  return '<div class="highlight leader-card" data-leader="'+spec.key+'" role="button" tabindex="0" aria-label="'+esc(spec.label)+'. '+esc(names)+'. Open full leaderboard."><div class="highlight-label">'+esc(spec.label)+'</div><div class="highlight-name">'+linkedNames+'</div><div class="highlight-value">'+esc(value)+'</div><div class="highlight-action">View full leaderboard →</div></div>';
}
function openLeaderboard(key){
  const games=filteredGames(),spec=dashboardLeaderboards(games).find(x=>x.key===key);
  if(!spec)return;
  const rows=sortedLeaderRows(spec);
  let lastValue=null,currentRank=0;
  const tableRows=rows.map((r,i)=>{
    const value=spec.score(r);
    let rank='—';
    if(value!==null){if(i===0||value!==lastValue)currentRank=i+1;rank=String(currentRank);lastValue=value}
    const nameCell=r.p?playerLink(r.p.id,spec.name(r)):esc(spec.name(r));
    return '<tr><td>'+rank+'</td><td>'+nameCell+'</td><td>'+esc(spec.format(r))+'</td><td>'+esc(spec.details(r))+'</td></tr>';
  }).join('');
  const subtitle=spec.key==='away'?currentSeason().name+' season · All teams':currentSeason().name+' season · '+(teamFilter==='ALL'?'All teams':team(teamFilter).name);
  const body='<div class="table-wrap"><table class="data-table leaderboard-table"><thead><tr><th>RANK</th><th>PLAYER / CONTRIBUTOR</th><th>VALUE</th><th>DETAILS</th></tr></thead><tbody>'+(tableRows||'<tr><td colspan="4">No players or contributors recorded.</td></tr>')+'</tbody></table></div><p class="metric-foot">Ties share a rank. Win percentage is shown for every player with a recorded win or loss; the dashboard leader requires at least 2 games.</p>';
  modal('Season leaderboard · '+spec.label,subtitle,body,'<button class="button button-primary" onclick="closeModal()">Close</button>');
}function dashboard(){const games=filteredGames(),s=teamStats(games),rows=allStatsRows(teamFilter);const played=rows.filter(x=>x.s.gp);const top=played[0],ppg=[...played].sort((a,b)=>b.s.ppg-a.s.ppg)[0],gp=[...played].sort((a,b)=>b.s.gp-a.s.gp)[0],fouls=[...played].sort((a,b)=>b.s.fouls-a.s.fouls)[0],best=[...played].filter(x=>x.s.gp>=2).sort((a,b)=>b.s.wpct-a.s.wpct)[0];const homeCount=games.filter(g=>g.venueType==='HOME');const dutyCount=new Map();homeCount.forEach(g=>(g.tableDuty||[]).forEach(id=>dutyCount.set(id,(dutyCount.get(id)||0)+1)));const duty=[...dutyCount].sort((a,b)=>b[1]-a[1])[0];let last=[...games].sort((a,b)=>a.date.localeCompare(b.date)).slice(-6);const bars=last.map((g,i)=>`<div class="bar-set"><div class="bar dark" style="height:${Math.max(4,g.ourScore/Math.max(1,...last.map(x=>x.ourScore))*83)}%" title="${g.ourScore} for"></div><div class="bar" style="height:${Math.max(4,g.opponentScore/Math.max(1,...last.map(x=>x.opponentScore))*83)}%" title="${g.opponentScore} against"></div><span class="bar-label">${new Date(g.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</span></div>`).join('');const highlights=dashboardLeaderboards(games);return `${heading('Season overview','A clear picture of how your teams are doing.',filterSelect())}<div class="success-box">${cloudMode ? (adminAllowed ? "Shared tracker is live. Changes sync for every visitor." : "Shared tracker is read only. Sign in as admin to update game data.") : "Sample season data is loaded for preview. Changes save in this browser."}</div><div class="metrics-grid">${metric('Games played',s.gp,`${s.w} wins · ${s.l} losses`,'▤')}${metric('Win percentage',`${s.wpct.toFixed(0)}%`,'Across selected teams','↗')}${metric('Points for',s.pf,`${s.avgf.toFixed(1)} average per game`,'◉')}${metric('Points against',s.pa,`${s.avga.toFixed(1)} average per game`,'◎')}</div><div class="content-grid"><article class="panel"><div class="panel-header"><h2>Scoring trend</h2><div class="team-pills"><span class="team-pill active">Points</span></div></div>${last.length?`<div class="chart">${bars}</div><div class="chart-legend"><span><i class="legend-dot"></i>Points for</span><span><i class="legend-dot pale"></i>Points against</span></div>`:`<div class="empty-state"><p>Score trends will appear here when games are added.</p></div>`}</article><article class="panel"><div class="panel-header"><h2>Recent results</h2><button class="text-link" data-go="games">All games →</button></div><div class="record-list">${[...games].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(g=>`<div class="record-row"><span class="record-score">${g.ourScore}–${g.opponentScore}</span><span class="record-desc"><strong>${esc(g.opponentName)}</strong><small>${fmtDate(g.date,{day:'numeric',month:'short'})} · ${team(g.teamId).shortName}</small></span>${resultTag(g)}</div>`).join('')||'<p class="metric-foot">Your results will show up here.</p>'}</div></article></div><section class="section-gap"><div class="panel-header"><h2>Season leaders</h2><button class="text-link" data-go="stats">View statistics →</button></div><div class="highlight-grid">${highlights.map(highlightCard).join('')}</div></section>`}
function gamePage(){const games=filteredGames();return `${heading('Games','Every result, all in one place.',filterSelect())}<div class="filters-row"><div class="filter-pills">${[['ALL','All games'],...db.teams.map(t=>[t.id,t.shortName])].map(([id,label])=>`<button class="filter-btn ${teamFilter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><span class="badge">${games.length} games</span></div>${gameRows(games)}`}
function statTable(filter){const rows=allStatsRows(filter);return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>PLAYER</th><th>GP</th><th>PTS</th><th>PPG</th><th>FOULS</th><th>W%</th><th>W–L</th></tr></thead><tbody>${rows.map(({p,s,all})=>`<tr data-player="${p.id}"><td><div class="player-name-cell">${avatar(p.name)}<span>${playerLink(p.id,p.name)}${filter==='ALL'&&db.teams.length>1?`<small style="display:block;color:#939b94;font-weight:400;font-size:9px">${db.teams.map(t=>{const n=seasonGames().filter(g=>g.teamId===t.id&&(g.appearances||[]).some(a=>a.playerId===p.id&&a.status==='PLAYED')).length;return n?`${n} ${t.shortName.toLowerCase()}`:''}).filter(Boolean).join(' · ')}</small>`:''}</span></div></td><td>${s.gp}</td><td>${s.points}</td><td>${s.ppg.toFixed(1)}</td><td>${s.fouls}</td><td>${s.wpct.toFixed(0)}%</td><td>${s.wins}–${s.losses}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">▥</div><strong>No player stats yet</strong><p>Player stats appear after you add games and record appearances.</p></div>`}
function statsPage(){const games=filteredGames(),s=teamStats(games),high=[...games].sort((a,b)=>b.ourScore-a.ourScore)[0],low=[...games].sort((a,b)=>a.ourScore-b.ourScore)[0],wins=games.filter(g=>result(g)==='WIN'),losses=games.filter(g=>result(g)==='LOSS');return `${heading('Statistics','The numbers behind your season.',filterSelect())}<div class="metrics-grid">${metric('Record',`${s.w}–${s.l}`,`${s.wpct.toFixed(1)}% win rate`,'↗')}${metric('Points for',s.pf,`${s.avgf.toFixed(1)} average per game`,'◉')}${metric('Points against',s.pa,`${s.avga.toFixed(1)} average per game`,'◎')}${metric('Highest scoring',high?.ourScore??'—',high?`vs ${esc(high.opponentName)}`:'No games yet','↑')}</div><div class="panel"><div class="panel-header"><h2>Player statistics</h2><span class="badge">${teamFilter==='ALL'?'All teams':esc(team(teamFilter).name)}</span></div>${statTable(teamFilter)}</div><div class="panel section-gap"><div class="panel-header"><h2>Season records</h2></div><div class="metrics-grid" style="margin:0">${metric('Lowest scoring',low?.ourScore??'—',low?`vs ${esc(low.opponentName)}`:'No games yet','↓')}${metric('Biggest win',wins.length?Math.max(...wins.map(g=>g.ourScore-g.opponentScore)):'—','Point margin','＋')}${metric('Biggest loss',losses.length?Math.max(...losses.map(g=>g.opponentScore-g.ourScore)):'—','Point margin','−')}${metric('Games recorded',s.gp,`${s.w} wins · ${s.l} losses`,'▤')}</div></div>`}
function playersPage(){let rows=allStatsRows(teamFilter).filter(x=>x.p.name.toLowerCase().includes(playerQuery.toLowerCase()));return `${heading('Players','Your players and their season contributions.',filterSelect())}<div class="filters-row"><input class="search" id="player-search" placeholder="⌕  Search players" value="${esc(playerQuery)}"/><span class="badge">${rows.length} players</span></div><div class="panel">${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>PLAYER</th><th>GP</th><th>PTS</th><th>PPG</th><th>WIN %</th></tr></thead><tbody>${rows.map(({p,s})=>`<tr data-player="${p.id}"><td><div class="player-name-cell">${avatar(p.name)}${playerLink(p.id,p.name)}</div></td><td>${teamFilter==='ALL'?s.gp:`${s.gp}/${filteredGames().length}`}</td><td>${s.points}</td><td>${s.ppg.toFixed(1)}</td><td>${s.wpct.toFixed(0)}%</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">♙</div><strong>${playerQuery?'No players match that search':'No players in this team yet'}</strong><p>Add a game or add players from More.</p><button class="button button-primary" onclick="openGame()">＋ Add game</button></div>`}</div>`}
function morePage(){const contributors=new Map();seasonGames().filter(g=>g.venueType==='HOME').forEach(g=>(g.tableDuty||[]).forEach(id=>contributors.set(id,(contributors.get(id)||0)+1)));return `${heading('More','Manage your teams, players, seasons and data.') }<div class="management-grid"><article class="panel"><div class="panel-header"><h2>Teams</h2><button class="button button-light" onclick="addTeam()">＋ Add team</button></div>${db.teams.map(t=>`<div class="manage-row"><div><strong>${esc(t.name)}</strong><small>${t.active?'Active':'Inactive'}</small></div><span class="small-actions"><button class="icon-btn" onclick="renameTeam('${t.id}')">Rename</button><button class="icon-btn" onclick="toggleTeam('${t.id}')">${t.active?'Deactivate':'Activate'}</button></span></div>`).join('')}</article><article class="panel"><div class="panel-header"><h2>Players</h2><button class="button button-light" onclick="addPlayer()">＋ Add player</button></div>${db.players.filter(p=>!p.deleted).map(p=>`<div class="manage-row"><div><strong>${playerLink(p.id,p.name)} ${p.squadNumber?`#${esc(p.squadNumber)}`:''}</strong><small>${p.active?'Active':'Inactive'}</small></div><span class="small-actions"><button class="icon-btn" onclick="editPlayer('${p.id}')">Edit</button><button class="icon-btn" onclick="togglePlayer('${p.id}')">${p.active?'Deactivate':'Activate'}</button><button class="icon-btn delete-player-btn" onclick="confirmDeletePlayer('${p.id}')">Remove</button></span></div>`).join('')||'<p class="metric-foot">No players in the roster yet.</p>'}</article><article class="panel"><div class="panel-header"><h2>Seasons</h2><button class="button button-light" onclick="addSeason()">＋ New season</button></div>${db.seasons.map(s=>`<div class="manage-row"><div><strong>${esc(s.name)}</strong><small>${s.active?'Active season':'Archived'}</small></div><span class="small-actions">${!s.active?`<button class="icon-btn" onclick="activateSeason('${s.id}')">Switch to</button>`:''}</span></div>`).join('')}</article><article class="panel"><div class="panel-header"><h2>Table duty</h2><span class="badge">Home games</span></div>${[...contributors].sort((a,b)=>b[1]-a[1]).map(([id,n])=>`<div class="manage-row"><strong>${esc(contributor(id).name)}</strong><span class="badge">${n} appearances</span></div>`).join('')||'<p class="metric-foot">Table duty contributors show here after home games.</p>'}</article><article class="panel"><div class="panel-header"><h2>Data & backup</h2></div><p class="metric-foot">${cloudMode ? "This is the shared tracker. Export a JSON backup regularly to keep a copy." : "Your data is saved in this browser. Export a JSON backup regularly to keep a copy."}</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="button button-primary" onclick="exportData()">↓ Export backup</button><button class="button button-outline" onclick="document.getElementById('import-file').click()">↑ Import backup</button></div><button class="text-link" style="margin-top:12px;color:#a34c42" onclick="resetDemo()">Reset sample data</button></article></div>`}
function render(){shell();const page=document.getElementById('page');page.innerHTML=({dashboard,games:gamePage,stats:statsPage,players:playersPage,more:morePage}[view]||dashboard)();bindPage();syncAccessUI();markAdminActions(page)}
function markAdminActions(root){const actions=/confirmDeletePlayer|deletePlayer|openGame|saveGame|confirmDeleteGame|deleteGame|addContributor|quickAddPlayer|resolveUnknown|createUnknown|addPlayer|saveNewPlayer|editPlayer|saveEditedPlayer|togglePlayer|addTeam|saveNewTeam|renameTeam|saveTeamName|toggleTeam|addSeason|saveNewSeason|activateSeason|commitImport|resetDemo|confirmReset|parseStats|setVenue|removeDuty|removeAppearance|updateAppearance|updateStatus/;root.querySelectorAll('[onclick]').forEach(el=>{if(actions.test(el.getAttribute('onclick')||''))el.dataset.adminOnly='true'})}
function syncAccessUI(){document.body.classList.toggle('cloud-mode',cloudMode);document.body.classList.toggle('is-admin',!cloudMode||adminAllowed);const status=document.getElementById('access-status'),button=document.getElementById('admin-access-button');if(status)status.textContent=!cloudMode?'Local only':adminAllowed?'Admin · synced': 'Shared · read only';if(button){button.hidden=!cloudMode;button.textContent=adminAllowed?'Admin sign out':'Admin sign in';button.onclick=adminAllowed?signOutAdmin:showAdminLogin}const season=document.getElementById('season-select');if(season)season.disabled=cloudMode&&!adminAllowed}
function showAdminLogin(){if(!cloudMode)return toast('Shared editing is not configured yet.');modal('Admin sign in','Only the configured admin account can update shared game data.','<div class="field"><label>ADMIN EMAIL</label><input id="admin-email" type="email" autocomplete="username" /></div><div class="field"><label>PASSWORD</label><input id="admin-password" type="password" autocomplete="current-password" /></div><div id="admin-login-error" class="warning-box" hidden></div>','<button class="button button-outline" onclick="closeModal()">Cancel</button><button id="admin-login-submit" class="button button-primary" type="button">Sign in</button>');document.getElementById('admin-email').value=adminEmail;document.getElementById('admin-login-submit').onclick=signInAdmin;document.getElementById('admin-password').onkeydown=e=>{if(e.key==='Enter')signInAdmin()}}
async function signInAdmin(){const email=document.getElementById('admin-email').value.trim(),password=document.getElementById('admin-password').value,errorBox=document.getElementById('admin-login-error');if(!email||!password){errorBox.hidden=false;errorBox.textContent='Enter your admin email and password.';return}const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error){errorBox.hidden=false;errorBox.textContent='Sign in failed. Check the email and password.';return}if(String(data.user?.email||'').toLowerCase()!==adminEmail){await supabaseClient.auth.signOut();errorBox.hidden=false;errorBox.textContent='This account is not the configured tracker admin.';return}closeModal();toast('Signed in. Loading shared data…')}
async function signOutAdmin(){await supabaseClient.auth.signOut();toast('Signed out. Tracker is read only.')}
async function loadCloudState(){const {data,error}=await supabaseClient.from('tracker_state').select('data').eq('id','main').maybeSingle();if(error){console.error('Tracker cloud load failed',error);return false}if(data?.data&&Array.isArray(data.data.games)){db=data.data;return true}if(adminAllowed){const {error:insertError}=await supabaseClient.from('tracker_state').insert({id:'main',data:db,updated_at:new Date().toISOString()});if(insertError){console.error('Tracker initial save failed',insertError);toast('Could not initialize shared data. Check the database setup.');return false}}else{const seed=initial();db={...seed,players:[],contributors:[],games:[]}}return true}
async function startTracker(){if(!cloudMode){render();return}if(!window.supabase?.createClient){document.getElementById('access-status').textContent='Cloud unavailable';render();toast('Could not load the shared data service.');return}supabaseClient=window.supabase.createClient(cloudConfig.supabaseUrl,cloudKey);const {data}=await supabaseClient.auth.getSession();cloudSession=data.session;adminAllowed=Boolean(adminEmail&&String(cloudSession?.user?.email||'').toLowerCase()===adminEmail);const loaded=await loadCloudState();if(!loaded)toast('Showing this browser’s saved data until the shared database is available.');supabaseClient.auth.onAuthStateChange((_event,session)=>{setTimeout(async()=>{cloudSession=session;adminAllowed=Boolean(adminEmail&&String(session?.user?.email||'').toLowerCase()===adminEmail);await loadCloudState();render()},0)});render()}
function bindPage(){document.querySelectorAll('[data-leader]').forEach(b=>{b.onclick=()=>openLeaderboard(b.dataset.leader);b.onkeydown=e=>{if(e.target!==b)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();openLeaderboard(b.dataset.leader)}}});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;render()});document.querySelectorAll('[data-game]').forEach(el=>el.onclick=()=>showGame(el.dataset.game));bindPlayerLinks(document);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{teamFilter=b.dataset.filter;render()});const ts=document.getElementById('team-select');if(ts)ts.onchange=()=>{teamFilter=ts.value;render()};const search=document.getElementById('player-search');if(search)search.oninput=()=>{const pos=search.selectionStart;playerQuery=search.value;const y=window.scrollY;render();const n=document.getElementById('player-search');n.focus();n.setSelectionRange(pos,pos);window.scrollTo(0,y)}}
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2400)}
function closeModal(){document.getElementById('overlay-root').innerHTML=''}
function modal(title,subtitle,body,footer=''){document.getElementById('overlay-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><section class="modal"><header class="modal-head"><div><h2>${title}</h2><p>${subtitle||''}</p></div><button class="close-btn" onclick="closeModal()">×</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;markAdminActions(document.getElementById('overlay-root'));bindPlayerLinks(document.getElementById('overlay-root'));document.getElementById('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()})}
function openGame(existingId=null){const old=existingId?seasonGames().find(g=>g.id===existingId):null;gameDraft={...old,appearances:old?JSON.parse(JSON.stringify(old.appearances||[])):[],tableDuty:old?[...(old.tableDuty||[])]:[]};renderGameForm()}
function renderGameForm(){let d=gameDraft;const activeTeams=db.teams.filter(t=>t.active);const teamOptions=activeTeams.map(t=>`<option value="${t.id}" ${d.teamId===t.id?'selected':''}>${esc(t.name)}</option>`).join('');const nameBox=d.rawText!==undefined?d.rawText:'';const score=d.ourScore!==undefined&&d.opponentScore!==undefined?(+d.ourScore>+d.opponentScore?'WIN':+d.ourScore<+d.opponentScore?'LOSS':'DRAW'):'Enter both scores';const statusOptions=['PLAYED','ATTENDED_DID_NOT_PLAY','UNAVAILABLE'];const rows=d.appearances.map((a,i)=>`<div class="preview-row"><div>${playerLink(a.playerId,player(a.playerId).name)}<select aria-label="Participation status" onchange="updateStatus(${i},this.value)">${statusOptions.map(s=>`<option value="${s}" ${a.status===s?'selected':''}>${s.replaceAll('_',' ')}</option>`).join('')}</select></div><input type="number" min="0" aria-label="Points" value="${a.stats?.points??0}" onchange="updateAppearance(${i},'points',this.value)"/><input type="number" min="0" aria-label="Fouls" value="${a.stats?.fouls??0}" onchange="updateAppearance(${i},'fouls',this.value)"/><button class="remove-row" onclick="removeAppearance(${i})">×</button></div>`).join('');let html=`<p class="form-section-title">01 — GAME DETAILS</p><div class="form-grid"><div class="field"><label>TEAM</label><select id="g-team">${teamOptions}</select></div><div class="field"><label>DATE</label><input type="date" id="g-date" value="${esc(d.date||new Date().toISOString().slice(0,10))}"/></div><div class="field"><label>OPPONENT</label><input id="g-opponent" placeholder="e.g. Leeds Eagles" value="${esc(d.opponentName||'')}"/></div><div class="field"><label>VENUE</label><div class="venue-toggle"><button class="${d.venueType!=='AWAY'?'active':''}" id="venue-home" onclick="setVenue('HOME')">⌂ Home</button><button class="${d.venueType==='AWAY'?'active':''}" id="venue-away" onclick="setVenue('AWAY')">↗ Away</button></div></div><div class="field"><label>OUR SCORE</label><input type="number" min="0" id="g-ours" placeholder="72" value="${d.ourScore??''}"/></div><div class="field"><label>OPPONENT SCORE</label><input type="number" min="0" id="g-theirs" placeholder="68" value="${d.opponentScore??''}"/></div></div><div class="score-result" id="score-preview">${score}</div><div class="field" style="margin-top:11px"><label>NOTES <span style="font-weight:400;color:#9aa19a">· optional</span></label><input id="g-notes" placeholder="Anything to remember about this game" value="${esc(d.notes||'')}"/></div><div class="form-section-title" style="margin-top:18px">02 — PLAYER STATS</div><div class="field"><label>PASTE PLAYER · POINTS · FOULS</label><textarea id="paste-stats" placeholder="Ben 14 2&#10;Dave 12 1&#10;John 8 3">${esc(nameBox)}</textarea></div><div class="parser-tools"><span id="parse-count">${d.appearances.length?`${d.appearances.length} players · ${d.appearances.filter(a=>a.status==='PLAYED').reduce((n,a)=>n+Number(a.stats.points||0),0)} points`: 'One player per line · e.g. Ben 14 2'}</span><button class="button button-light" onclick="parseStats()">Preview paste</button></div><div id="warnings"></div><div class="preview-list">${rows}</div><div style="display:flex;gap:8px;margin-top:10px"><select class="select-small" id="add-player-select"><option value="">＋ Add player appearance</option>${db.players.filter(p=>!p.deleted&&p.active&&!d.appearances.some(a=>a.playerId===p.id)).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button class="button button-outline" onclick="quickAddPlayer()">New player</button></div>`;
if(d.venueType!=='AWAY')html+=`<div class="form-section-title" style="margin-top:19px">03 — TABLE DUTY <span style="font-weight:400;letter-spacing:0">· HOME GAME</span></div><div class="field"><label>WHO RAN THE TABLE?</label><select id="duty-select"><option value="">＋ Add contributor</option>${db.contributors.filter(c=>c.active&&!d.tableDuty.includes(c.id)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div>${d.tableDuty.map((id,i)=>`<span class="duty-chip">${esc(contributor(id).name)} <button style="border:0;background:none;color:inherit" onclick="removeDuty(${i})">×</button></span>`).join('')} <button class="text-link" onclick="addContributor()">＋ New contributor</button></div>`;
modal(d.id?'Edit game':'Add a game','Record the result, then paste the player line scores.',html,`<button class="button button-outline" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveGame()">${d.id?'Save changes':'Save game'} →</button>`);['g-team','g-date','g-opponent','g-ours','g-theirs','g-notes'].forEach(id=>{const el=document.getElementById(id);el?.addEventListener('input',captureDraft);el?.addEventListener('change',captureDraft)});document.getElementById('paste-stats').addEventListener('input',e=>gameDraft.rawText=e.target.value);document.getElementById('duty-select')?.addEventListener('change',e=>{if(e.target.value){gameDraft.tableDuty.push(e.target.value);renderGameForm()}})}
function captureDraft(){if(!gameDraft)return;gameDraft.teamId=document.getElementById('g-team').value;gameDraft.date=document.getElementById('g-date').value;gameDraft.opponentName=document.getElementById('g-opponent').value;gameDraft.ourScore=document.getElementById('g-ours').value;gameDraft.opponentScore=document.getElementById('g-theirs').value;gameDraft.notes=document.getElementById('g-notes').value;const result=gameDraft.ourScore!==''&&gameDraft.opponentScore!==''?(+gameDraft.ourScore>+gameDraft.opponentScore?'WIN':+gameDraft.ourScore<+gameDraft.opponentScore?'LOSS':'DRAW'):'Enter both scores';document.getElementById('score-preview').textContent=result}
function setVenue(v){captureDraft();gameDraft.venueType=v;if(v==='AWAY')gameDraft.tableDuty=[];renderGameForm()}
function parseLine(line){let t=line.trim();if(!t)return null;let parts=t.includes(',')?t.split(',').map(x=>x.trim()):t.split(/\s+-\s+|\t+|\s{2,}/).map(x=>x.trim());if(parts.length>=3&&parts.slice(-2).every(x=>/^\d+$/.test(x)))return{name:parts.slice(0,-2).join(' ').replace(/\s*[-,]\s*$/,''),points:+parts.at(-2),fouls:+parts.at(-1)};let m=t.match(/^(.+?)\s+(-?\d+)\s+(-?\d+)$/);return m?{name:m[1].replace(/[\s,-]+$/,''),points:+m[2],fouls:+m[3]}:null}
function similarity(a,b){a=a.toLowerCase().replace(/[^a-z]/g,'');b=b.toLowerCase().replace(/[^a-z]/g,'');const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const tmp=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=tmp}}return 1-row[b.length]/Math.max(a.length,b.length,1)}
function parseStats(){captureDraft();const text=document.getElementById('paste-stats').value;gameDraft.rawText=text;const existing=gameDraft.appearances.map(a=>a.playerId);let out=[],warnings=[];for(const [index,line]of text.split(/\r?\n/).entries()){if(!line.trim())continue;const parsed=parseLine(line);if(!parsed){warnings.push(`Line ${index+1}: couldn’t read “${esc(line)}”. Use Player Points Fouls.`);continue}if(parsed.points<0||parsed.fouls<0){warnings.push(`${esc(parsed.name)} has a negative value. Stats must be zero or more.`);continue}const p=db.players.find(x=>!x.deleted&&x.name.toLowerCase()===parsed.name.toLowerCase());if(!p){out.push({...parsed,unknown:true});continue}if(existing.includes(p.id)||out.some(x=>x.playerId===p.id)){warnings.push(`Duplicate line for ${esc(p.name)} was skipped.`);continue}out.push({...parsed,playerId:p.id,status:'PLAYED',stats:{points:parsed.points,fouls:parsed.fouls}})}gameDraft.parsed=out;const prev=gameDraft.appearances.filter(a=>!a._fromPaste);gameDraft.appearances=[...prev,...out.filter(x=>x.playerId)];renderGameForm();const w=document.getElementById('warnings');w.innerHTML=[...warnings.map(x=>`<div class="warning-box">${x}</div>`),...out.filter(x=>x.unknown).map(x=>suggestResolution(x))].join('');document.getElementById('parse-count').textContent=`${out.filter(x=>x.playerId).length} recognized · ${out.filter(x=>x.unknown).length} unknown · ${out.filter(x=>x.playerId).reduce((n,x)=>n+x.points,0)} points`;if(!warnings.length&&!out.some(x=>x.unknown))toast(`${out.length} player lines ready`)}
function updateAppearance(i,key,val){gameDraft.appearances[i].stats[key]=Math.max(0,+val||0)}function updateStatus(i,val){gameDraft.appearances[i].status=val;if(val!=='PLAYED')gameDraft.appearances[i].stats={points:0,fouls:0};renderGameForm()}function removeAppearance(i){gameDraft.appearances.splice(i,1);renderGameForm()}function removeDuty(i){gameDraft.tableDuty.splice(i,1);renderGameForm()}function quickAddPlayer(){const id=document.getElementById('add-player-select').value;if(!id)return;gameDraft.appearances.push({playerId:id,status:'PLAYED',stats:{points:0,fouls:0}});renderGameForm()}
function suggestResolution(parsed){const candidates=db.players.filter(p=>!p.deleted).map(p=>({p,score:similarity(p.name,parsed.name)})).sort((a,b)=>b.score-a.score).slice(0,3);return `<div class="warning-box">Unknown player <strong>${esc(parsed.name)}</strong>${candidates[0]?.score>.5?` · Did you mean <strong>${esc(candidates[0].p.name)}</strong>?`:''}<div style="display:flex;gap:7px;margin-top:7px"><select class="select-small" id="resolve-${esc(parsed.name)}"><option value="">Choose existing player…</option>${db.players.filter(p=>!p.deleted).map(p=>`<option value="${p.id}" ${p.id===candidates[0]?.p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button class="button button-light" onclick="resolveUnknown('${esc(parsed.name)}')">Use player</button><button class="button button-outline" onclick="createUnknown('${esc(parsed.name)}')">Create</button></div></div>`}
function resolveUnknown(name){const id=document.getElementById(`resolve-${name}`).value;if(!id)return toast('Choose a player first');const item=gameDraft.parsed.find(x=>x.name===name);item.playerId=id;item.status='PLAYED';item.stats={points:item.points,fouls:item.fouls};gameDraft.appearances.push(item);renderGameForm();document.getElementById('warnings').innerHTML=(gameDraft.parsed||[]).filter(x=>x.unknown&&!x.playerId).map(x=>suggestResolution(x)).join('')}
function createUnknown(name){const p={id:uid(),name,active:true,createdAt:new Date().toISOString()};db.players.push(p);const item=gameDraft.parsed.find(x=>x.name===name);item.playerId=p.id;item.status='PLAYED';item.stats={points:item.points,fouls:item.fouls};gameDraft.appearances.push(item);save();renderGameForm();document.getElementById('warnings').innerHTML=(gameDraft.parsed||[]).filter(x=>x.unknown&&!x.playerId).map(x=>suggestResolution(x)).join('')}
function addContributor(){const name=prompt('Contributor name');if(!name?.trim())return;const c={id:uid(),name:name.trim(),active:true};db.contributors.push(c);gameDraft.tableDuty.push(c.id);save();renderGameForm()}
function saveGame(){captureDraft();const d=gameDraft;if(!d.teamId||!d.date||!d.opponentName.trim()||d.ourScore===''||d.opponentScore==='')return toast('Complete team, date, opponent and both scores first.');if(+d.ourScore<0||+d.opponentScore<0||!Number.isFinite(+d.ourScore)||!Number.isFinite(+d.opponentScore))return toast('Scores must be valid numbers of zero or more.');if((d.appearances||[]).some(a=>a.stats.points<0||a.stats.fouls<0))return toast('Player stats must be zero or more.');if(d.venueType==='AWAY'&&d.tableDuty.length)return toast('Only home games can have table duty.');const unique=new Set(d.appearances.map(a=>a.playerId));if(unique.size!==d.appearances.length)return toast('A player can appear only once per game.');let g={id:d.id||uid(),seasonId:d.seasonId||currentSeason().id,teamId:d.teamId,date:d.date,opponentName:d.opponentName.trim(),venueType:d.venueType||'HOME',ourScore:+d.ourScore,opponentScore:+d.opponentScore,notes:d.notes||'',appearances:d.appearances.map(a=>({playerId:a.playerId,status:a.status,stats:{...a.stats}})),tableDuty:d.venueType==='AWAY'?[]:d.tableDuty,createdAt:d.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(!db.teams.some(t=>t.id===g.teamId))return toast('Choose a valid team.');const ix=db.games.findIndex(x=>x.id===g.id);if(ix<0)db.games.push(g);else db.games[ix]=g;save();closeModal();render();toast(ix<0?'Game saved — season stats updated':'Game updated')}
function showGame(id){const g=db.games.find(x=>x.id===id);if(!g)return;selectedGame=id;const played=(g.appearances||[]).filter(a=>a.status==='PLAYED'),attended=(g.appearances||[]).filter(a=>a.status==='ATTENDED_DID_NOT_PLAY'),unavailable=(g.appearances||[]).filter(a=>a.status==='UNAVAILABLE'),points=played.reduce((n,a)=>n+Number(a.stats?.points||0),0);let rows=played.map(a=>`<tr data-player="${a.playerId}"><td><div class="player-name-cell">${avatar(player(a.playerId).name)}${playerLink(a.playerId,player(a.playerId).name)}</div></td><td>${a.stats?.points??0}</td><td>${a.stats?.fouls??0}</td></tr>`).join('');const body=`<div class="detail-score">${esc(g.opponentName)} <span style="color:#9aa29b">${g.ourScore}–${g.opponentScore}</span></div><div class="detail-meta">${esc(team(g.teamId).name)} · ${g.venueType} · ${fmtDate(g.date)}</div><div class="detail-result">${resultTag(g)}</div><div class="panel" style="padding:0;box-shadow:none"><div class="table-wrap"><table class="data-table"><thead><tr><th>PLAYER</th><th>PTS</th><th>F</th></tr></thead><tbody>${rows||'<tr><td colspan="3">No playing appearances recorded.</td></tr>'}</tbody></table></div></div><div class="detail-meta" style="margin-top:9px">Team total: <strong>${points} player points</strong> · ${played.length} played</div>${attended.length?`<div class="detail-section-title">ATTENDED, DID NOT PLAY</div><div>${attended.map(a=>`<span class="duty-chip">${playerLink(a.playerId,player(a.playerId).name)}</span>`).join('')}</div>`:''}${unavailable.length?`<div class="detail-section-title">UNAVAILABLE</div><div>${unavailable.map(a=>`<span class="badge">${playerLink(a.playerId,player(a.playerId).name)}</span>`).join(' ')}</div>`:''}${g.notes?`<div class="detail-section-title">GAME NOTES</div><p class="detail-meta">${esc(g.notes)}</p>`:''}${g.venueType==='HOME'?`<div class="detail-section-title">TABLE DUTY</div><div>${(g.tableDuty||[]).map(id=>`<span class="duty-chip">◷ ${esc(contributor(id).name)}</span>`).join('')||'<span class="detail-meta">Not recorded</span>'}</div>`:''}`;modal('Game detail',`${fmtDate(g.date)} · ${esc(team(g.teamId).name)}`,body,`<button class="button button-danger" onclick="confirmDeleteGame('${g.id}')">Delete</button><div style="display:flex;gap:8px"><button class="button button-outline" onclick="closeModal()">Close</button><button class="button button-primary" onclick="openGame('${g.id}')">Edit game</button></div>`)}
function confirmDeleteGame(id){const g=db.games.find(x=>x.id===id);modal('Delete this game?','This removes the game and its attached appearance and table-duty records.',`<div class="confirm-box"><strong>${esc(g.opponentName)} · ${g.ourScore}–${g.opponentScore}</strong><br>This action cannot be undone.</div>`,`<button class="button button-outline" onclick="showGame('${id}')">Keep game</button><button class="button button-danger" onclick="deleteGame('${id}')">Delete game</button>`)}function deleteGame(id){db.games=db.games.filter(g=>g.id!==id);save();closeModal();render();toast('Game deleted')}
function showPlayer(id){selectedPlayer=id;const p=player(id),s=playerStats(id,seasonGames()),played=s.played.slice().sort((a,b)=>b.g.date.localeCompare(a.g.date));const perTeam=db.teams.map(t=>({t,s:playerStats(id,seasonGames().filter(g=>g.teamId===t.id))})).filter(x=>x.s.gp||x.s.attended);const history=played.map(({g,a})=>`<tr data-game="${g.id}"><td>${fmtDate(g.date,{day:'numeric',month:'short'})}</td><td>${esc(team(g.teamId).shortName)}</td><td>${esc(g.opponentName)}</td><td>${resultTag(g)}</td><td>${a.stats?.points??0}</td><td>${a.stats?.fouls??0}</td></tr>`).join('');const body=`<div class="profile-head">${avatar(p.name)}<div><h1>${esc(p.name)}</h1><p>${p.squadNumber?`Squad #${esc(p.squadNumber)} · `:''}${p.active?'Active player':'Inactive player'}</p></div></div><div class="profile-section"><h2>Overall · ${esc(currentSeason().name)}</h2><div class="stat-chips"><div class="stat-chip"><span>Appearances</span><strong>${s.gp}</strong></div><div class="stat-chip"><span>Points</span><strong>${s.points}</strong></div><div class="stat-chip"><span>PPG</span><strong>${s.ppg.toFixed(1)}</strong></div><div class="stat-chip"><span>Fouls</span><strong>${s.fouls}</strong></div><div class="stat-chip"><span>Record</span><strong>${s.wins}–${s.losses}</strong></div><div class="stat-chip"><span>Win rate</span><strong>${s.wpct.toFixed(1)}%</strong></div></div></div>${perTeam.map(x=>`<div class="profile-section"><h2>${esc(x.t.name)} <span class="badge">${x.s.gp}/${seasonGames().filter(g=>g.teamId===x.t.id).length} GP</span></h2><div class="stat-chips"><div class="stat-chip"><span>Appearances</span><strong>${x.s.gp}</strong></div><div class="stat-chip"><span>Points</span><strong>${x.s.points}</strong></div><div class="stat-chip"><span>PPG</span><strong>${x.s.ppg.toFixed(1)}</strong></div><div class="stat-chip"><span>Fouls</span><strong>${x.s.fouls}</strong></div><div class="stat-chip"><span>Record</span><strong>${x.s.wins}–${x.s.losses}</strong></div><div class="stat-chip"><span>Win rate</span><strong>${x.s.wpct.toFixed(1)}%</strong></div></div></div>`).join('')}<div class="profile-section"><h2>Attendance</h2><p class="detail-meta">${s.gp} played · ${s.attended} attended (including played) · ${s.unavailable} unavailable${s.attendanceRate!==null?` · ${s.attendanceRate.toFixed(0)}% attendance rate`:''}</p>${(()=>{const away=seasonGames().filter(g=>g.venueType==='AWAY'),att=away.filter(g=>(g.appearances||[]).some(a=>a.playerId===id&&['PLAYED','ATTENDED_DID_NOT_PLAY'].includes(a.status))).length,known=away.filter(g=>(g.appearances||[]).some(a=>a.playerId===id&&a.status));return away.length?`<p class="detail-meta">Away: ${away.length} team games, ${att} attended${known.length?`, ${(att/away.length*100).toFixed(0)}% of all away games`:''}.</p>`:''})()}</div><div class="profile-section"><h2>Game history <span class="badge">Played · ${played.length}</span></h2><div class="table-wrap"><table class="data-table"><thead><tr><th>DATE</th><th>TEAM</th><th>OPPONENT</th><th>RESULT</th><th>PTS</th><th>F</th></tr></thead><tbody>${history||'<tr><td colspan="6">No games played this season.</td></tr>'}</tbody></table></div></div>`;modal('Player profile',`Season stats for ${esc(p.name)}`,body,`<button class="button button-outline" onclick="closeModal()">Close</button><button class="button button-primary" onclick="editPlayer('${id}')">Edit player</button>`);document.querySelectorAll('[data-game]').forEach(el=>el.onclick=()=>showGame(el.dataset.game))}
function simpleForm(title,label,value,saveFn,extra=''){modal(title,'Keep player records consistent across every team.',`<div class="form-grid"><div class="field"><label>${label}</label><input id="simple-name" value="${esc(value||'')}"/></div>${extra}</div>`,`<button class="button button-outline" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="${saveFn}">Save</button>`)}function addPlayer(){simpleForm('Add player','PLAYER NAME','','saveNewPlayer','<div class="field"><label>SQUAD NUMBER · OPTIONAL</label><input id="simple-number" type="number" min="0"/></div>')}function saveNewPlayer(){const n=document.getElementById('simple-name').value.trim();if(!n)return toast('Enter a player name');if(db.players.some(p=>!p.deleted&&p.name.toLowerCase()===n.toLowerCase()))return toast('A player with that name already exists');db.players.push({id:uid(),name:n,squadNumber:document.getElementById('simple-number').value||'',active:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});save();closeModal();render();toast('Player added')}
function editPlayer(id){const p=player(id);simpleForm('Edit player','PLAYER NAME',p.name,`saveEditedPlayer('${id}')`,`<div class="field"><label>SQUAD NUMBER · OPTIONAL</label><input id="simple-number" type="number" min="0" value="${esc(p.squadNumber||'')}"/></div>`)}function saveEditedPlayer(id){const n=document.getElementById('simple-name').value.trim(),p=player(id);if(!n)return toast('Enter a player name');if(db.players.some(x=>!x.deleted&&x.id!==id&&x.name.toLowerCase()===n.toLowerCase()))return toast('That player name is already in use');p.name=n;p.squadNumber=document.getElementById('simple-number').value;p.updatedAt=new Date().toISOString();save();closeModal();render();toast('Player updated')}
function togglePlayer(id){const p=player(id);p.active=!p.active;save();render();toast(`${p.name} ${p.active?'activated':'deactivated'}`)}function confirmDeletePlayer(id){const p=player(id),count=db.games.reduce((n,g)=>n+(g.appearances||[]).filter(a=>a.playerId===id).length,0),message=count?`${count} saved game appearance${count===1?'':'s'} will stay in game history under ${esc(p.name)}. This removes the player from the roster and all player leaderboards.`:'This removes the player from the roster and all player leaderboards.';modal('Remove player?',esc(p.name),`<div class="confirm-box">${message}</div>`,`<button class="button button-outline" onclick="closeModal()">Cancel</button><button class="button button-danger" onclick="deletePlayer('${id}')">Remove player</button>`)}function deletePlayer(id){const p=db.players.find(x=>x.id===id&&!x.deleted);if(!p)return;p.deleted=true;p.active=false;p.deletedAt=new Date().toISOString();save();closeModal();render();toast(`${p.name} removed from player lists`)}function addTeam(){simpleForm('Add team','TEAM NAME','','saveNewTeam','<div class="field"><label>SHORT NAME</label><input id="simple-short" maxlength="8" placeholder="e.g. 3RD"/></div>')}function saveNewTeam(){const n=document.getElementById('simple-name').value.trim();if(!n)return toast('Enter a team name');db.teams.push({id:uid(),name:n,shortName:document.getElementById('simple-short').value.trim()||n.slice(0,4).toUpperCase(),active:true,createdAt:new Date().toISOString()});save();closeModal();render();toast('Team added')}function renameTeam(id){const t=team(id);simpleForm('Rename team','TEAM NAME',t.name,`saveTeamName('${id}')`,`<div class="field"><label>SHORT NAME</label><input id="simple-short" maxlength="8" value="${esc(t.shortName)}"/></div>`)}function saveTeamName(id){const n=document.getElementById('simple-name').value.trim();if(!n)return toast('Enter a team name');const t=team(id);t.name=n;t.shortName=document.getElementById('simple-short').value.trim()||n.slice(0,4).toUpperCase();save();closeModal();render();toast('Team updated')}function toggleTeam(id){const t=team(id);t.active=!t.active;save();render();toast(`${t.name} ${t.active?'activated':'deactivated'}`)}
function addSeason(){simpleForm('Create a season','SEASON NAME','','saveNewSeason')}function saveNewSeason(){const n=document.getElementById('simple-name').value.trim();if(!n)return toast('Enter a season name');if(db.seasons.some(s=>s.name.toLowerCase()===n.toLowerCase()))return toast('That season already exists');db.seasons.forEach(s=>s.active=false);db.seasons.push({id:uid(),name:n,active:true,createdAt:new Date().toISOString()});save();closeModal();render();toast('Season created')}function activateSeason(id){db.seasons.forEach(s=>s.active=s.id===id);save();render();toast(`Switched to ${currentSeason().name}`)}
function exportData(){const blob=new Blob([JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`baseline-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup exported')}
document.getElementById('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const incoming=JSON.parse(await file.text());const errors=[];if(!Array.isArray(incoming.seasons)||!Array.isArray(incoming.teams)||!Array.isArray(incoming.players)||!Array.isArray(incoming.games))throw Error('Backup must contain seasons, teams, players and games.');const seasonIds=new Set(incoming.seasons.map(x=>x.id)),teamIds=new Set(incoming.teams.map(x=>x.id)),playerIds=new Set(incoming.players.map(x=>x.id));for(const g of incoming.games){if(!seasonIds.has(g.seasonId)||!teamIds.has(g.teamId)||!g.date||!g.opponentName||!Number.isFinite(+g.ourScore)||+g.ourScore<0||!Number.isFinite(+g.opponentScore)||+g.opponentScore<0)errors.push(`Invalid game: ${g.opponentName||g.id}`);const ids=new Set();for(const a of g.appearances||[]){if(!playerIds.has(a.playerId)||ids.has(a.playerId)||!['PLAYED','ATTENDED_DID_NOT_PLAY','UNAVAILABLE'].includes(a.status)||Object.values(a.stats||{}).some(v=>!Number.isFinite(+v)||+v<0))errors.push(`Invalid appearance in ${g.opponentName}`);ids.add(a.playerId)}if(g.tableDuty?.length&&g.venueType!=='HOME')errors.push(`Table duty on away game: ${g.opponentName}`)}if(errors.length)throw Error(errors.slice(0,5).join('\n'));modal('Import backup?','Preview the data before replacing the records in this browser.',`<div class="success-box">Ready to import ${incoming.games.length} games, ${incoming.players.length} players, ${incoming.teams.length} teams and ${incoming.seasons.length} seasons.</div><p class="detail-meta">This replaces the current local data. Export a backup first if you need to keep it.</p>`,`<button class="button button-outline" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="commitImport()">Import data</button>`);window.pendingImport=incoming}catch(err){modal('Import could not be validated','The existing data has not been changed.',`<div class="warning-box" style="white-space:pre-line">${esc(err.message)}</div>`,`<button class="button button-primary" onclick="closeModal()">Close</button>`)}finally{e.target.value=''}};
function commitImport(){db=window.pendingImport;save();closeModal();render();toast('Backup imported')}
function resetDemo(){modal('Reset sample data?','Restore the development sample records.',`<div class="confirm-box">This will replace all data currently saved in this browser with the sample season and games.</div>`,`<button class="button button-outline" onclick="closeModal()">Cancel</button><button class="button button-danger" onclick="confirmReset()">Reset data</button>`)}function confirmReset(){db=initial();save();closeModal();render();toast('Sample data restored')}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;render()}));document.getElementById('add-game-top').onclick=()=>openGame();document.getElementById('mobile-add').onclick=()=>openGame();document.getElementById('season-select').onchange=e=>{db.seasons.forEach(s=>s.active=s.id===e.target.value);save();render()};
window.openGame=openGame;window.closeModal=closeModal;window.updateAppearance=updateAppearance;window.updateStatus=updateStatus;window.removeAppearance=removeAppearance;window.removeDuty=removeDuty;window.quickAddPlayer=quickAddPlayer;window.parseStats=parseStats;window.saveGame=saveGame;window.setVenue=setVenue;window.resolveUnknown=resolveUnknown;window.createUnknown=createUnknown;window.addContributor=addContributor;window.showGame=showGame;window.showPlayer=showPlayer;window.confirmDeleteGame=confirmDeleteGame;window.deleteGame=deleteGame;window.addPlayer=addPlayer;window.saveNewPlayer=saveNewPlayer;window.editPlayer=editPlayer;window.saveEditedPlayer=saveEditedPlayer;window.togglePlayer=togglePlayer;window.confirmDeletePlayer=confirmDeletePlayer;window.deletePlayer=deletePlayer;window.addTeam=addTeam;window.saveNewTeam=saveNewTeam;window.renameTeam=renameTeam;window.saveTeamName=saveTeamName;window.toggleTeam=toggleTeam;window.addSeason=addSeason;window.saveNewSeason=saveNewSeason;window.activateSeason=activateSeason;window.exportData=exportData;window.commitImport=commitImport;window.resetDemo=resetDemo;window.confirmReset=confirmReset;window.BaselineCalculations={teamStats,playerStats,result,parseLine,similarity,tableDutyStats};
startTracker();
